/* Structured notes remain portable, searchable notes; calculations never execute code. */
(function(root){'use strict';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=(s,max)=>typeof s==='string'&&s.length<=max;
function localDate(date=new Date()){return [date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-');}
function validDate(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(s+'T12:00:00');return Number.isFinite(+d)&&localDate(d)===s;}
const journalFields={focus:'What matters today',space:'What I want to make room for',win:'A moment worth keeping',release:'What I can leave here',next:'One small step for tomorrow',free:'A page of my own'};
function journal(date){if(!validDate(date))throw Error('Choose a valid journal date.');return {date,mood:'',tab:'morning',fields:Object.fromEntries(Object.keys(journalFields).map(k=>[k,'']))};}
function journalHTML(j){return '<p>'+escape(j.date)+(j.mood?' · '+escape(j.mood):'')+'</p>'+Object.entries(journalFields).filter(([k])=>j.fields[k]).map(([k,label])=>'<h2>'+label+'</h2>'+j.fields[k].split('\n').map(line=>'<p>'+escape(line)+'</p>').join('')).join('');}
function newMap(uid){return {nodes:[{id:uid(),parent:null,label:'My central idea',body:'',relation:'',x:560,y:350}],selected:null};}
function descendants(map,id){const result=new Set([id]);let changed=true;while(changed){changed=false;for(const n of map.nodes)if(result.has(n.parent)&&!result.has(n.id)){result.add(n.id);changed=true;}}return result;}
function addBranch(map,parentId,uid){if(map.nodes.length>=60)throw Error('This map has 60 thoughts. Start another map to keep it readable.');const parent=map.nodes.find(n=>n.id===parentId)||map.nodes[0],count=map.nodes.filter(n=>n.parent===parent.id).length,angle=count*2.4;const node={id:uid(),parent:parent.id,label:'New thought',body:'',relation:'connects to',x:Math.max(16,Math.min(2200,parent.x+Math.cos(angle)*250)),y:Math.max(16,Math.min(4000,parent.y+Math.sin(angle)*160+90))};map.nodes.push(node);map.selected=node.id;return node;}
function arrange(map){let maxDepth=0;for(const node of map.nodes){let p=node,depth=0;while(p.parent){depth++;p=map.nodes.find(n=>n.id===p.parent);}maxDepth=Math.max(maxDepth,depth);}const gap=Math.min(220,2100/Math.max(1,maxDepth));let leaf=0;const visit=(n,depth)=>{const children=map.nodes.filter(c=>c.parent===n.id);if(children.length){for(const c of children)visit(c,depth+1);n.y=(children[0].y+children.at(-1).y)/2;}else n.y=24+leaf++*116;n.x=24+depth*gap;};visit(map.nodes.find(n=>n.parent===null),0);}
function mapHTML(map){const visit=n=>'<li><strong>'+escape(n.label)+'</strong>'+(n.relation?' — '+escape(n.relation):'')+(n.body?'<p>'+escape(n.body).replace(/\n/g,'<br>')+'</p>':'')+(map.nodes.some(c=>c.parent===n.id)?'<ul>'+map.nodes.filter(c=>c.parent===n.id).map(visit).join('')+'</ul>':'')+'</li>';const r=map.nodes.find(n=>n.parent===null);return r?'<ul>'+visit(r)+'</ul>':'';}
function mapSVG(map,{mini=false}={}){const nodes=map.nodes,w=Math.max(900,...nodes.map(n=>n.x+200)),h=Math.max(560,...nodes.map(n=>n.y+105));const paths=nodes.filter(n=>n.parent).map(n=>{const p=nodes.find(p=>p.id===n.parent);return p?`<path d="M${p.x+85},${p.y+38} C${p.x+180},${p.y+38} ${n.x-50},${n.y+38} ${n.x+85},${n.y+38}"/><text x="${(p.x+n.x)/2+85}" y="${(p.y+n.y)/2+28}">${escape(n.relation.slice(0,24))}</text>`:'';}).join('');return `<svg xmlns="http://www.w3.org/2000/svg" class="map-links" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="2">${paths}</g>${mini?nodes.map(n=>`<rect x="${n.x}" y="${n.y}" width="170" height="76" rx="12"/><text x="${n.x+12}" y="${n.y+42}">${escape(n.label.slice(0,23))}</text>`).join(''):''}</svg>`;}
function mathRows(uid){return [{id:uid(),label:'Guests',name:'guests',expression:'8',whatIf:'10',unit:'people'},{id:uid(),label:'Cost per guest',name:'cost',expression:'12.5',whatIf:'',unit:''},{id:uid(),label:'Total',name:'total',expression:'guests * cost',whatIf:'',unit:''}];}
function mathRun(rows,calculate,scenario=false){
 const names=new Map(),duplicates=new Set(),results=new Map(),busy=new Set();
 for(const r of rows){const name=r.name.trim().toLowerCase();if(names.has(name))duplicates.add(name);names.set(name,r);}
 function solve(row){if(results.has(row.id))return results.get(row.id);if(busy.has(row.id))throw Error('Circular reference: '+row.name);busy.add(row.id);
  try{const name=row.name.trim().toLowerCase();if(!/^[a-z][a-z0-9_]{0,19}$/.test(name)||['pi','e'].includes(name))throw Error('Use a unique name: letters, digits, and underscores.');if(duplicates.has(name))throw Error('This name is used twice.');const raw=(scenario&&row.whatIf.trim()?row.whatIf:row.expression).trim().replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-');if(!raw)throw Error('Enter an expression.');if(raw.length>180)throw Error('Keep expressions under 180 characters.');const tokens=raw.match(/(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?|[A-Za-z][A-Za-z0-9_]*|[+*/^()%\-]|\s+/g)||[];if(tokens.join('')!==raw)throw Error('Use numbers, names, and arithmetic operators.');const expanded=tokens.map(t=>{if(!/^[A-Za-z]/.test(t))return t;const key=t.toLowerCase();if(key==='pi')return '('+Math.PI+')';if(key==='e')return '('+Math.E+')';const dependency=names.get(key);if(!dependency)throw Error('Unknown name: '+t);const result=solve(dependency);if(result.error)throw Error('Fix '+key+' first.');return '('+result.value+')';}).join('');const value=calculate(expanded);const result={value,expanded};results.set(row.id,result);return result;}catch(e){const result={error:e.message};results.set(row.id,result);return result;}finally{busy.delete(row.id);}}
 return rows.map(solve);
}
function mathHTML(sheet,calculate){const base=mathRun(sheet.rows,calculate),alt=sheet.scenario?mathRun(sheet.rows,calculate,true):[];return sheet.rows.map((r,i)=>'<h2>'+escape(r.label||r.name)+'</h2><p>'+escape(r.name+' = '+r.expression)+'</p><p>'+escape(base[i].error||String(base[i].value)+(r.unit?' '+r.unit:''))+'</p>'+(sheet.scenario?'<p>What if: '+escape(r.whatIf||r.expression)+' → '+escape(alt[i].error||String(alt[i].value)+(r.unit?' '+r.unit:''))+'</p>':'')).join('');}
function validateNote(n){
 if(n.journal){const j=n.journal;if(!validDate(j.date)||!['','quiet','steady','bright','busy','heavy'].includes(j.mood)||!['morning','evening','free'].includes(j.tab)||!j.fields||Object.keys(journalFields).some(k=>!text(j.fields[k],20000))||Object.keys(j.fields).some(k=>!Object.hasOwn(journalFields,k)))throw Error('Invalid journal page');}
 if(n.mindmap){const m=n.mindmap;if(!Array.isArray(m.nodes)||!m.nodes.length||m.nodes.length>60)throw Error('Invalid mind map');const ids=new Set();for(const p of m.nodes){if(!text(p.id,100)||!/^[-A-Za-z0-9_]+$/.test(p.id)||ids.has(p.id)||!text(p.label,120)||!text(p.body,4000)||!text(p.relation,60)||!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<0||p.x>2200||p.y<0||p.y>8000)throw Error('Invalid map thought');ids.add(p.id);}const roots=m.nodes.filter(p=>p.parent===null);if(roots.length!==1)throw Error('Invalid map root');for(const p of m.nodes){let cursor=p;const seen=new Set();while(cursor.parent!==null){if(seen.has(cursor.id)||!ids.has(cursor.parent))throw Error('Invalid map connection');seen.add(cursor.id);cursor=m.nodes.find(n=>n.id===cursor.parent);}}}
 if(n.mathSheet){const m=n.mathSheet;if(typeof m.scenario!=='boolean'||!Array.isArray(m.rows)||!m.rows.length||m.rows.length>50)throw Error('Invalid math sheet');const ids=new Set();for(const r of m.rows){if(!text(r.id,100)||!/^[-A-Za-z0-9_]+$/.test(r.id)||ids.has(r.id)||!text(r.label,100)||!text(r.name,20)||!text(r.expression,180)||!text(r.whatIf,180)||!text(r.unit,24))throw Error('Invalid calculation line');ids.add(r.id);}}
 if(n.photo){const p=n.photo;for(const key of ['data','preview'])if(p[key]!==undefined&&(!text(p[key],18*1024*1024)||p[key]&&!/^data:image\/(jpeg|png|webp);base64,/i.test(p[key])))throw Error('Invalid photo source');if(![0,90,180,270].includes(p.rotation)||!Array.isArray(p.blocks)||p.blocks.length>200)throw Error('Invalid photo text');for(const b of p.blocks)if(!text(b.text,10000)||typeof b.selected!=='boolean'||!Array.isArray(b.box)||b.box.length!==4||b.box.some(v=>!Number.isFinite(v)||v<0||v>1))throw Error('Invalid photo block');}
 for(const [mode,key]of [['photo','photo'],['journal','journal'],['mindmap','mindmap'],['math','mathSheet']])if(n.inputMode===mode&&(n.type!=='note'||!n[key]))throw Error('Missing mode data');return n;
}
const api={escape,localDate,validDate,journalFields,journal,journalHTML,newMap,descendants,addBranch,arrange,mapHTML,mapSVG,mathRows,mathRun,mathHTML,validateNote};if(typeof module!=='undefined')module.exports=api;else root.NotaCreative=api;
})(typeof window!=='undefined'?window:globalThis);
